import fs from "fs";
import path from "path";
import formidable from "formidable";

export const config = {
  api: {
    bodyParser: false, // Next.js no parsea automáticamente los archivos
  },
};

export default async function handler(req, res) {
  if (req.method !== "POST") {
    return res.status(405).json({ error: "Método no permitido" });
  }

  const uploadDir = path.join(process.cwd(), "public/uploads");

  // Crear carpeta si no existe
  if (!fs.existsSync(uploadDir)) {
    fs.mkdirSync(uploadDir, { recursive: true });
  }

  try {
    const form = formidable({
      uploadDir,
      keepExtensions: true,
      multiples: false, // por si acaso
      maxFileSize: 10 * 1024 * 1024, // 10MB máximo
    });

    const parsed = await new Promise((resolve, reject) => {
      form.parse(req, (err, fields, files) => {
        if (err) reject(err);
        else resolve({ fields, files });
      });
    });

    const { files } = parsed;
    const file = files.photo || files.file; // según tu input
    if (!file) return res.status(400).json({ error: "No se subió archivo" });

    // formidable puede devolver array o objeto
    const oldPath = Array.isArray(file) ? file[0].filepath : file.filepath;
    const fileName = Array.isArray(file)
      ? file[0].originalFilename
      : file.originalFilename;

    const newPath = path.join(uploadDir, fileName);

    await fs.promises.rename(oldPath, newPath);

    return res.status(200).json({ success: true, file: `/uploads/${fileName}` });
  } catch (e) {
    console.error("Error subiendo archivo:", e);
    return res.status(500).json({ error: "Error interno del servidor" });
  }
}
